from datetime import datetime, timezone
from decimal import Decimal
from ledgerly.adjustments import outage_refund
from ledgerly.models import Payment
from ledgerly.errors import BillingError
from ledgerly import audit

T0 = datetime(2026,10,1,tzinfo=timezone.utc)
def p(amount="2000.00", status="captured"):
    return Payment("pay_1","inv_1",Decimal(amount),status=status,created_at=T0,captured_at=T0)

# at threshold no approval
x=p(); outage_refund(x, Decimal("1000.00"), T0); print("threshold ok", x.refunded_amount)
# above threshold requires approval
try: outage_refund(p(), Decimal("1000.01"), T0)
except BillingError as e: print("approval:", e.code)
# with approval
x=p(); outage_refund(x, Decimal("1000.01"), T0, approved_by="mgr"); print("approved", x.refunded_amount)
# full refund sets status
x=p("80.00"); outage_refund(x, Decimal("80.00"), T0); print("status", x.status)
# non-captured
try: outage_refund(p(status="authorized"), Decimal("1.00"), T0)
except BillingError as e: print("state:", e.code)
# over refund
x=p("80.00")
try: outage_refund(x, Decimal("81.00"), T0)
except BillingError as e: print("exceeds:", e.code)
# non-positive
try: outage_refund(p(), Decimal("0"), T0)
except BillingError as e: print("nonpositive:", e.code)
# idempotency
x=p("80.00"); outage_refund(x, Decimal("8.00"), T0, idempotency_key="k1")
outage_refund(x, Decimal("8.00"), T0, idempotency_key="k1"); print("idem", x.refunded_amount, len(audit.events()))
EOF"}

